// ============================================================================
// F1 RE-ENGAGEMENT 4H FOLLOW-UP
// Cron cada 15 min: lista leads pending followup -> envia template Meta -> marca followup_sent=true
// Template requerido APPROVED: lead_waiting_4h_followup_v1 (es_PE, MARKETING)
// Doctrina #11 - deterministic backbone first
// ============================================================================

const META_TOKEN = $env.META_SYSTEM_USER_TOKEN;
const AUDIT_TOKEN = $env.AUDIT_INTERNAL_TOKEN;
const ERP_BASE = 'https://erp.livskin.site';
const WA_PHONE_NUMBER_ID = '1071476852722953';  // +51 947 741 117 (Livskin productivo)
const TEMPLATE_NAME = 'lead_waiting_4h_followup_v1';
const TEMPLATE_LANG = 'es_PE';

const TREATMENT_LABELS = {
  botox: 'Botox',
  acido: 'Ácido Hialurónico',
  prp: 'Plasma Rico en Plaquetas',
  limpieza: 'Limpieza Facial',
  hilos: 'Hilos Tensores',
  salmon: 'Esperma de Salmón',
  exosomas: 'Exosomas',
};

if (!META_TOKEN || !AUDIT_TOKEN) {
  return [{ json: { error: 'env vars missing' } }];
}

// 1. Fetch pending followups
let pending;
try {
  pending = await this.helpers.httpRequest({
    method: 'GET',
    url: ERP_BASE + '/api/internal/wa-state/pending-followup',
    qs: { hours_since_inbound: 4 },
    headers: { 'X-Internal-Token': AUDIT_TOKEN },
    json: true,
    timeout: 10000,
  });
} catch (e) {
  return [{ json: { error: 'fetch failed: ' + e.message } }];
}

const items = (pending && pending.items) || [];
if (items.length === 0) {
  return [{ json: { skipped: true, reason: 'no pending followups', checked_at: new Date().toISOString() } }];
}

const results = { sent: [], errors: [], total: items.length };

for (const row of items) {
  const phoneNoPlus = (row.phone_lead || '').replace(/^\+/, '');
  const ctx = row.context_json || {};
  const treatmentKey = ctx.q1_treatment || ctx.referral_product || null;
  const treatmentLabel = treatmentKey ? TREATMENT_LABELS[treatmentKey] : 'tu consulta';
  // Sanitizar profile_name:
  // - Si nombre invalido (emoji, username, <3 chars alfa) -> empty string (Meta normaliza espacios)
  // - Si nombre valido -> solo PRIMER nombre (sin apellidos)
  function sanitizeName(name) {
    if (!name || typeof name !== 'string') return '';
    const trimmed = name.trim();
    if (trimmed.length < 3) return '';
    if (/[:@_]/.test(trimmed)) return '';
    if (/[0-9]{3,}/.test(trimmed)) return '';
    const alphaChars = (trimmed.match(/[a-zA-ZáéíóúñüÁÉÍÓÚÑÜ]/g) || []).length;
    if (alphaChars < 3) return '';
    // Solo el PRIMER nombre (split por espacio + take first)
    return trimmed.split(/\s+/)[0].slice(0, 25);
  }
  const profileName = sanitizeName(ctx.profile_name || '');

  // Send template
  try {
    const meta_response = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://graph.facebook.com/v21.0/' + WA_PHONE_NUMBER_ID + '/messages',
      headers: {
        Authorization: 'Bearer ' + META_TOKEN,
        'Content-Type': 'application/json',
      },
      body: {
        messaging_product: 'whatsapp',
        recipient_type: 'individual',
        to: phoneNoPlus,
        type: 'template',
        template: {
          name: TEMPLATE_NAME,
          language: { code: TEMPLATE_LANG },
          components: [
            {
              type: 'body',
              parameters: [
                // Si profileName vacio, paso espacio (Meta no acepta empty string en template params)
                { type: 'text', text: profileName || ' ' },
                { type: 'text', text: treatmentLabel },
              ],
            },
          ],
        },
      },
      json: true,
      timeout: 15000,
    });
    results.sent.push({ phone: row.phone_lead, wamid: meta_response?.messages?.[0]?.id });
  } catch (e) {
    results.errors.push({ phone: row.phone_lead, error: e.message });
    continue;
  }

  // Mark followup_sent = true en state
  try {
    const newContext = { ...ctx, followup_sent: true, followup_sent_at: new Date().toISOString() };
    await this.helpers.httpRequest({
      method: 'POST',
      url: ERP_BASE + '/api/internal/wa-state',
      headers: { 'X-Internal-Token': AUDIT_TOKEN, 'Content-Type': 'application/json' },
      body: {
        phone_lead: row.phone_lead,
        state: row.state,
        last_intent: row.last_intent,
        context_json: newContext,
        increment_outbound_count: true,
        last_outbound_text: '[TEMPLATE lead_waiting_4h_followup_v1]',
      },
      json: true,
      timeout: 10000,
    });
  } catch (e) {
    results.errors.push({ phone: row.phone_lead, error: 'state_upsert: ' + e.message });
  }
}

return [{ json: { ok: true, results, ran_at: new Date().toISOString() } }];
